export const DAILY_FLAG_ORDER = Object.keys(DAILY_FLAG_CONFIG) as FraudFlagType[];

const defaultDailyFlag: DailyFlagEntry = {
  label: '',
  description: '',
  icon: FlagIcon,
  accentText: 'text-muted-foreground',
  accentBg: 'bg-muted',
};

// The backend may add a FraudFlagType value the client doesn't know yet — fall back to a
// neutral flag entry rather than letting a raw config[type] lookup return undefined.
export function getDailyFlag(type: FraudFlagType): DailyFlagEntry {
  return DAILY_FLAG_CONFIG[type] ?? { ...defaultDailyFlag, label: snakeCaseToCapitalizedCase(type) };
}
