import type { DailyReviewDayStats, DailyReviewShift, FraudFlagType } from '~/client';
import { DAILY_FLAG_ORDER } from '~/constants/workshifts/dailyReviewConfig';

export interface FlagSummaryRow {
  key: FraudFlagType;
  count: number;
}

export function computeFlagSummary(shifts: DailyReviewShift[]): FlagSummaryRow[] {
  return DAILY_FLAG_ORDER.map((key) => ({
    key,
    count: shifts.filter((shift) => shift.flag_types?.includes(key)).length,
  }));
}

export interface ReviewProgress {
  reviewed: number;
  reviewable: number;
  pct: number;
}

export function computeReviewProgress(shifts: DailyReviewShift[]): ReviewProgress {
  const reviewable = shifts.filter((shift) => shift.is_reviewable).length;
  const reviewed = shifts.filter((shift) => shift.is_reviewable && shift.is_reviewed).length;
  return { reviewed, reviewable, pct: reviewable === 0 ? 0 : Math.round((reviewed / reviewable) * 100) };
}

export function computeDelta(current: number | null | undefined, previous: number | null | undefined): number | null {
  if (current == null || previous == null || previous === 0) return null;
  return Math.round(((current - previous) / previous) * 100);
}

export function formatDelta(delta: number): string {
  const arrow = delta > 0 ? '▲' : delta < 0 ? '▼' : '·';
  return `${arrow} ${Math.abs(delta)}%`;
}

export interface DayRates {
  surveyPct: number | null;
  dph: number | null;
  hoursPerCanvasser: number | null;
  doorsPerCanvasser: number | null;
}

export function computeRates(stats: DailyReviewDayStats): DayRates {
  const { canvassers_count: count, doors, surveys, net_hours: hours } = stats;
  return {
    surveyPct: doors != null && surveys != null && doors > 0 ? Math.round((surveys / doors) * 1000) / 10 : null,
    dph: doors != null && hours > 0 ? Math.round((doors / hours) * 10) / 10 : null,
    hoursPerCanvasser: count > 0 ? Math.round((hours / count) * 10) / 10 : null,
    doorsPerCanvasser: doors != null && count > 0 ? Math.round(doors / count) : null,
  };
}

export type DailyReviewSortKey = 'most-flags' | 'lowest-survey' | 'canvasser';

export function shiftSurveyPct(shift: DailyReviewShift): number | null {
  if (shift.doors == null || shift.surveys == null || shift.doors === 0) return null;
  return Math.round((shift.surveys / shift.doors) * 100);
}

export function shiftCanvasserName(shift: DailyReviewShift): string {
  return `${shift.canvasser.first_name ?? ''} ${shift.canvasser.last_name ?? ''}`.trim();
}

export function sortDailyReviewShifts(shifts: DailyReviewShift[], sortKey: DailyReviewSortKey): DailyReviewShift[] {
  const sorted = [...shifts];
  switch (sortKey) {
    case 'most-flags':
      return sorted.sort(
        (a, b) =>
          (b.flag_types?.length ?? 0) - (a.flag_types?.length ?? 0) ||
          shiftCanvasserName(a).localeCompare(shiftCanvasserName(b))
      );
    case 'lowest-survey':
      return sorted.sort(
        (a, b) =>
          (shiftSurveyPct(a) ?? Number.POSITIVE_INFINITY) - (shiftSurveyPct(b) ?? Number.POSITIVE_INFINITY) ||
          shiftCanvasserName(a).localeCompare(shiftCanvasserName(b))
      );
    case 'canvasser':
      return sorted.sort((a, b) => shiftCanvasserName(a).localeCompare(shiftCanvasserName(b)));
  }
}
